static uint64_t z_t84_fastHash(const z_t84_t* self) {
    return z_fasthash_stringview(*self);
}
static z_t84_t z_t84_trim(const z_t84_t* self);
static z_t84_t z_t84_trim(const z_t84_t* self) {
    const char* p = self->data;
    const char* end = self->data + self->size;
    while (p < end && z_ascii_is_ws((unsigned char)*p)) p++;
    while (end > p && z_ascii_is_ws((unsigned char)end[-1])) end--;
    z_t84_t out = { .size = (uint64_t)(end - p), .data = p };
    return out;
}

